'use client';
import { useCallback, useEffect, useId, useRef, useState, type KeyboardEvent, type ReactNode } from 'react';
import { useStudioMotion } from '../../motion';
import { StudioCanvas, type OrbitInspectHandle } from '../../three';
import type { EffectProps } from '../../types';
import { MaquetteDrawing } from './fallback';
import { Scene, type LimitPreset, type ViewInfo } from './scene';
import styles from './styles.module.css';

type Params = { damping: number; step: number; limits: LimitPreset; autoRotate: boolean; accent: string };

const ZOOM_STEP = 1.18;
const describe = (v: ViewInfo) => `Viewing from ${Math.round(v.azimuth)}°, ${Math.round(v.elevation)}° above the ground, zoom ${v.zoom.toFixed(1)}×.`;

/** Mount/unmount signal from inside the canvas: false whenever StudioCanvas is showing its fallback. */
function Ready({ onChange }: { onChange: (ready: boolean) => void }) {
  useEffect(() => { onChange(true); return () => onChange(false); }, [onChange]);
  return null;
}

const Icon = ({ children }: { children: ReactNode }) => (
  <svg viewBox="0 0 20 20" aria-hidden="true" focusable="false">{children}</svg>
);

export default function OrbitInspectControls({ params }: EffectProps<Params>) {
  const { reduced } = useStudioMotion();
  const hintId = useId();
  const viewer = useRef<HTMLDivElement>(null);
  const handle = useRef<OrbitInspectHandle | null>(null);
  const readout = useRef<HTMLParagraphElement>(null);
  const last = useRef<ViewInfo | null>(null);
  const timer = useRef(0);
  const [ready, setReady] = useState(false);
  const [announce, setAnnounce] = useState('');
  const step = (params.step * Math.PI) / 180;

  const onView = useCallback((v: ViewInfo) => {
    last.current = v;
    if (readout.current) readout.current.textContent = `${String(Math.round(v.azimuth)).padStart(3, '0')}°  ·  ${Math.round(v.elevation)}° up  ·  ${v.zoom.toFixed(1)}×`;
  }, []);
  // Screen readers hear the resulting view once a move has settled, never per frame.
  const settle = useCallback(() => {
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => { if (last.current) setAnnounce(describe(last.current)); }, reduced ? 50 : 450);
  }, [reduced]);
  useEffect(() => () => window.clearTimeout(timer.current), []);

  const act = useCallback((fn: (h: OrbitInspectHandle) => void) => {
    const h = handle.current;
    if (!h) return;
    fn(h);
    settle();
  }, [settle]);

  // Wheel: zoom only while the viewer has focus, or for ctrl/⌘ + wheel (how trackpad pinch arrives) while hovering.
  // Otherwise the event is left alone and the page scrolls past the canvas.
  useEffect(() => {
    const el = viewer.current;
    if (!el || !ready) return;
    const onWheel = (e: WheelEvent) => {
      const focused = el.contains(document.activeElement);
      if (!(focused || e.ctrlKey || e.metaKey) || !handle.current) return;
      e.preventDefault();
      const dy = e.deltaMode === 1 ? e.deltaY * 16 : e.deltaMode === 2 ? e.deltaY * 400 : e.deltaY;
      handle.current.zoom(Math.pow(0.95, dy * (e.ctrlKey ? 0.04 : 0.01)));
      settle();
    };
    el.addEventListener('wheel', onWheel, { passive: false, capture: true });
    return () => el.removeEventListener('wheel', onWheel, { capture: true });
  }, [ready, settle]);

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (e.target !== e.currentTarget || e.altKey || e.ctrlKey || e.metaKey) return;
    const map: Record<string, (h: OrbitInspectHandle) => void> = {
      ArrowLeft: (h) => h.rotate(step), ArrowRight: (h) => h.rotate(-step),
      ArrowUp: (h) => h.rotate(0, step / 2), ArrowDown: (h) => h.rotate(0, -step / 2),
      '+': (h) => h.zoom(ZOOM_STEP), '=': (h) => h.zoom(ZOOM_STEP), '-': (h) => h.zoom(1 / ZOOM_STEP), _: (h) => h.zoom(1 / ZOOM_STEP),
      0: (h) => h.reset(), Home: (h) => h.reset(),
    };
    const fn = map[e.key];
    if (!fn) return;
    e.preventDefault();
    act(fn);
  };

  return (
    <div className={styles.root}>
      <div
        ref={viewer}
        className={styles.viewer}
        tabIndex={ready ? 0 : undefined}
        role={ready ? 'application' : undefined}
        aria-roledescription={ready ? '3D viewer' : undefined}
        aria-label={ready ? 'Pavilion maquette' : undefined}
        aria-describedby={ready ? hintId : undefined}
        aria-keyshortcuts={ready ? 'ArrowLeft ArrowRight ArrowUp ArrowDown + - 0' : undefined}
        onKeyDown={onKeyDown}
      >
        <StudioCanvas
          label="Pavilion maquette, sample model"
          description="A 1:50 architectural model on a grey board plinth: a white cantilevered roof on four slender steel columns and a basswood core, a raised podium with steps, a glazed back wall, three foam trees and two coloured scale figures. Drag, the arrow keys or the toolbar orbit the camera around it."
          camera={{ fov: 30, near: 0.1, far: 120, position: [6, 5, 8] }}
          fallback={<MaquetteDrawing accent={params.accent} />}
        >
          <Ready onChange={setReady} />
          <Scene
            ref={handle}
            accent={params.accent}
            damping={params.damping}
            step={params.step}
            limits={params.limits}
            autoRotate={params.autoRotate}
            onView={onView}
            onSettle={settle}
          />
        </StudioCanvas>
        <p className={styles.tag} aria-hidden="true">Pavilion study · 1:50 · sample model</p>
        {ready ? <p ref={readout} className={styles.readout} aria-hidden="true" /> : null}
      </div>

      <div className={styles.bar}>
        <div role="group" aria-label="Camera controls" className={styles.toolbar}>
          <span className={styles.group}>
            <span className={styles.legend} aria-hidden="true">Orbit</span>
            <button type="button" disabled={!ready} aria-label={`Rotate left ${params.step}°`} onClick={() => act((h) => h.rotate(step))}>
              <Icon><path d="M7 5 3.5 8.5 7 12" /><path d="M3.8 8.5H11a5 5 0 0 1 0 10H8" /></Icon>
            </button>
            <button type="button" disabled={!ready} aria-label={`Rotate right ${params.step}°`} onClick={() => act((h) => h.rotate(-step))}>
              <Icon><path d="m13 5 3.5 3.5L13 12" /><path d="M16.2 8.5H9a5 5 0 0 0 0 10h3" /></Icon>
            </button>
            <button type="button" disabled={!ready} aria-label="Tilt up" onClick={() => act((h) => h.rotate(0, step / 2))}>
              <Icon><path d="M10 16V4M5.5 8.5 10 4l4.5 4.5" /></Icon>
            </button>
            <button type="button" disabled={!ready} aria-label="Tilt down" onClick={() => act((h) => h.rotate(0, -step / 2))}>
              <Icon><path d="M10 4v12M5.5 11.5 10 16l4.5-4.5" /></Icon>
            </button>
          </span>
          <span className={styles.group}>
            <span className={styles.legend} aria-hidden="true">Zoom</span>
            <button type="button" disabled={!ready} aria-label="Zoom out" onClick={() => act((h) => h.zoom(1 / ZOOM_STEP))}>
              <Icon><path d="M4.5 10h11" /></Icon>
            </button>
            <button type="button" disabled={!ready} aria-label="Zoom in" onClick={() => act((h) => h.zoom(ZOOM_STEP))}>
              <Icon><path d="M4.5 10h11M10 4.5v11" /></Icon>
            </button>
          </span>
          <button type="button" className={styles.reset} disabled={!ready} onClick={() => act((h) => h.reset())}>
            <Icon><circle cx="10" cy="10" r="6" /><circle cx="10" cy="10" r="1.6" /></Icon>
            Reset view
          </button>
        </div>
        <p id={hintId} className={styles.hint}>
          {ready
            ? 'Drag to orbit (sideways on touch). Focus the viewer, then use the arrow keys, + / − or the wheel; pinch or Ctrl + wheel zooms while hovering. 0 resets.'
            : 'Interactive 3D is unavailable here, so a drawing of the model from the home view is shown instead.'}
        </p>
        <p className={styles.srOnly} aria-live="polite">{announce}</p>
      </div>
    </div>
  );
}

/**
 * Baked ground shadows for the maquette. The key light is fixed to the model (the CAMERA orbits, not the sun), so a
 * shadow texture drawn once with canvas2d stays correct from every viewpoint — real-looking architecture shadows with
 * no shadow-map pass at any quality level.
 */
import { CanvasTexture, SRGBColorSpace } from 'three';
import { COLUMNS, CORE, FIGURE_HEIGHT, FIGURES, FIN, KEY_DIR, PODIUM, ROOF, SLAB, TREE_TRUNK, TREES, type Box } from './model';

const PPU = 160; // texels per model metre
const X0 = SLAB.x[0], Z0 = SLAB.z[0];
export const SHADOW_SIZE = { w: Math.round((SLAB.x[1] - SLAB.x[0]) * PPU), h: Math.round((SLAB.z[1] - SLAB.z[0]) * PPU) };

/** Ground-plane offset (dx, dz) per metre of height for the fixed key light. */
const len = Math.hypot(...KEY_DIR);
const L = KEY_DIR.map((v) => v / len) as [number, number, number];
const OFF = { x: -L[0] / L[1], z: -L[2] / L[1] };

const px = (x: number) => (x - X0) * PPU;
const pz = (z: number) => (z - Z0) * PPU;

type Ctx = CanvasRenderingContext2D;

/** Fill a soft shape: drawn 10 000 px off-canvas, only its blurred shadow lands on the texture (works everywhere). */
function soft(ctx: Ctx, blur: number, alpha: number, draw: (c: Ctx) => void): void {
  ctx.save();
  ctx.translate(-10000, 0);
  ctx.shadowOffsetX = 10000;
  ctx.shadowBlur = blur;
  ctx.shadowColor = `rgba(34, 26, 16, ${alpha})`;
  ctx.fillStyle = '#000';
  ctx.beginPath();
  draw(ctx);
  ctx.fill();
  ctx.restore();
}

/** Footprint of a box swept along the light from its base height `g` to its top: the box's cast shadow. */
function sweep(c: Ctx, b: Box, g: number, steps = 6): void {
  const h = b.y[1] - g;
  for (let i = 0; i <= steps; i++) {
    const t = (i / steps) * h;
    c.rect(px(b.x[0] + OFF.x * t), pz(b.z[0] + OFF.z * t), (b.x[1] - b.x[0]) * PPU, (b.z[1] - b.z[0]) * PPU);
  }
}

export function bakeShadowTexture(): CanvasTexture | null {
  if (typeof document === 'undefined') return null;
  const canvas = document.createElement('canvas');
  canvas.width = SHADOW_SIZE.w;
  canvas.height = SHADOW_SIZE.h;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;
  const floor = PODIUM.y[1];

  // Cast shadows (soft penumbra grows with height, so the roof is the softest).
  soft(ctx, 26, 0.5, (c) => {
    const h = ROOF.y[0] - floor;
    c.rect(px(ROOF.x[0] + OFF.x * h), pz(ROOF.z[0] + OFF.z * h), (ROOF.x[1] - ROOF.x[0]) * PPU, (ROOF.z[1] - ROOF.z[0]) * PPU);
  });
  soft(ctx, 14, 0.55, (c) => sweep(c, CORE, floor));
  soft(ctx, 10, 0.45, (c) => sweep(c, FIN, floor));
  soft(ctx, 6, 0.5, (c) => {
    for (const [x, z] of COLUMNS) {
      const h = ROOF.y[0] - floor;
      c.moveTo(px(x - 0.03), pz(z));
      c.lineTo(px(x + 0.03), pz(z));
      c.lineTo(px(x + 0.03 + OFF.x * h), pz(z + OFF.z * h));
      c.lineTo(px(x - 0.03 + OFF.x * h), pz(z + OFF.z * h));
      c.closePath();
    }
  });
  soft(ctx, 16, 0.4, (c) => {
    for (const t of TREES) {
      const h = TREE_TRUNK + t.r * 0.6;
      c.ellipse(px(t.x + OFF.x * h), pz(t.z + OFF.z * h), t.r * PPU * 1.1, t.r * PPU * 0.95, 0, 0, Math.PI * 2);
    }
  });
  soft(ctx, 4, 0.45, (c) => {
    for (const f of FIGURES) {
      c.moveTo(px(f.x - 0.04), pz(f.z));
      c.lineTo(px(f.x + 0.04), pz(f.z));
      c.lineTo(px(f.x + 0.04 + OFF.x * FIGURE_HEIGHT), pz(f.z + OFF.z * FIGURE_HEIGHT));
      c.lineTo(px(f.x - 0.04 + OFF.x * FIGURE_HEIGHT), pz(f.z + OFF.z * FIGURE_HEIGHT));
      c.closePath();
    }
  });
  // Contact occlusion: a tight dark seam where walls meet the floor, and under the podium lip.
  soft(ctx, 5, 0.35, (c) => { c.rect(px(CORE.x[0]), pz(CORE.z[0]), (CORE.x[1] - CORE.x[0]) * PPU, (CORE.z[1] - CORE.z[0]) * PPU); });
  soft(ctx, 7, 0.28, (c) => { c.rect(px(PODIUM.x[0]), pz(PODIUM.z[0]), (PODIUM.x[1] - PODIUM.x[0]) * PPU, (PODIUM.z[1] - PODIUM.z[0]) * PPU); });

  const tex = new CanvasTexture(canvas);
  tex.colorSpace = SRGBColorSpace;
  tex.anisotropy = 4;
  return tex;
}

/** UVs for a ground plane covering `b` (x/z extent), expressed in the slab-wide shadow texture. */
export function groundUv(b: Box): { u: [number, number]; v: [number, number] } {
  const W = SLAB.x[1] - SLAB.x[0], H = SLAB.z[1] - SLAB.z[0];
  // CanvasTexture is flipped: canvas row 0 (back of the model, z min) is v = 1.
  return { u: [(b.x[0] - X0) / W, (b.x[1] - X0) / W], v: [1 - (b.z[1] - Z0) / H, 1 - (b.z[0] - Z0) / H] };
}

/** Soft radial contact shadow for the plinth on the stage floor. */
export function blobTexture(): CanvasTexture | null {
  if (typeof document === 'undefined') return null;
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const g = c.getContext('2d');
  if (!g) return null;
  const grad = g.createRadialGradient(64, 64, 0, 64, 64, 64);
  grad.addColorStop(0, 'rgba(20,16,10,0.85)');
  grad.addColorStop(0.5, 'rgba(20,16,10,0.4)');
  grad.addColorStop(1, 'rgba(20,16,10,0)');
  g.fillStyle = grad;
  g.fillRect(0, 0, 128, 128);
  const tex = new CanvasTexture(c);
  tex.colorSpace = SRGBColorSpace;
  return tex;
}

'use client';
/**
 * No-WebGL fallback: the same maquette data drawn as an SVG axonometric from the three-quarter "home" view.
 * Faces are projected with an orthographic camera and painted back-to-front; shading follows the fixed key light.
 */
import { useMemo } from 'react';
import { CORE, COLORS, COLUMNS, FIGURES, FIN, GLASS, PLINTH, PODIUM, ROOF, SLAB, STEPS, TREE_TRUNK, TREES, type Box } from './model';

const AZ = 0.62, EL = 0.52;
const right = [Math.cos(AZ), 0, -Math.sin(AZ)];
const up = [-Math.sin(AZ) * Math.sin(EL), Math.cos(EL), -Math.cos(AZ) * Math.sin(EL)];
const toward = [Math.sin(AZ) * Math.cos(EL), Math.sin(EL), Math.cos(AZ) * Math.cos(EL)];
const S = 60;
const dot = (a: number[], b: number[]) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const proj = (p: number[]) => [dot(p, right) * S, -dot(p, up) * S] as const;
const pts = (ps: number[][]) => ps.map((p) => proj(p).map((v) => v.toFixed(1)).join(',')).join(' ');

/** The three faces of a box visible from the front-right-top camera, with a shade factor each. */
function faces(b: Box) {
  const [x0, x1] = b.x, [y0, y1] = b.y, [z0, z1] = b.z;
  return [
    { shade: 1, points: pts([[x0, y1, z0], [x1, y1, z0], [x1, y1, z1], [x0, y1, z1]]) },
    { shade: 0.9, points: pts([[x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]]) },
    { shade: 0.74, points: pts([[x1, y0, z0], [x1, y0, z1], [x1, y1, z1], [x1, y1, z0]]) },
  ];
}
const shadeHex = (hex: string, k: number) => {
  const n = parseInt(hex.slice(1), 16);
  const c = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((v) => Math.round(v * k));
  return `rgb(${c[0]} ${c[1]} ${c[2]})`;
};
const depth = (b: Box) => dot([(b.x[0] + b.x[1]) / 2, (b.y[0] + b.y[1]) / 2, (b.z[0] + b.z[1]) / 2], toward);

export function MaquetteDrawing({ accent }: { accent: string }) {
  const { solids, view } = useMemo(() => {
    const colH = ROOF.y[0] - PODIUM.y[1];
    const list: { box: Box; color: string; opacity?: number }[] = [
      { box: PLINTH, color: COLORS.board }, { box: SLAB, color: COLORS.paper }, { box: PODIUM, color: COLORS.paper },
      ...STEPS.map((box) => ({ box, color: COLORS.paper })),
      { box: CORE, color: COLORS.basswood }, { box: FIN, color: COLORS.basswood },
      ...COLUMNS.map(([x, z]) => ({ box: { x: [x - 0.03, x + 0.03], y: [PODIUM.y[1], PODIUM.y[1] + colH], z: [z - 0.03, z + 0.03] } as Box, color: COLORS.steel })),
      { box: GLASS, color: '#cfdfe2', opacity: 0.45 },
      { box: ROOF, color: COLORS.paper },
    ];
    const corners = [PLINTH.x, PLINTH.y, PLINTH.z].reduce<number[][]>((acc, r, axis) => acc.flatMap((p) => r.map((v) => { const q = [...p]; q[axis] = v; return q; })), [[0, 0, 0]]);
    const xy = corners.map(proj);
    const xs = xy.map((p) => p[0]), ys = [...xy.map((p) => p[1]), proj([0, ROOF.y[1] + 0.2, 0])[1]];
    const pad = 14;
    return {
      solids: list.sort((a, b) => depth(a.box) - depth(b.box)),
      view: `${Math.min(...xs) - pad} ${Math.min(...ys) - pad} ${Math.max(...xs) - Math.min(...xs) + pad * 2} ${Math.max(...ys) - Math.min(...ys) + pad * 2 + 18}`,
    };
  }, []);

  return (
    <svg viewBox={view} role="img" aria-label="Drawing of the pavilion maquette from the front right: a cantilevered white roof on four slender steel columns and a basswood core, on a raised podium with steps, three foam trees and two scale figures, set on a grey board plinth." style={{ width: 'min(100%, 560px)', height: 'auto', maxHeight: 'calc(100% - 56px)' }}>
      <ellipse cx={proj([0.2, PLINTH.y[0], 0])[0]} cy={proj([0.2, PLINTH.y[0], 0])[1] + 10} rx={240} ry={26} fill="#11110f" opacity="0.1" />
      {solids.map(({ box, color, opacity }, i) => (
        <g key={i} opacity={opacity}>
          {faces(box).map((f, j) => (
            <polygon key={j} points={f.points} fill={shadeHex(color, f.shade)} stroke="#11110f" strokeOpacity="0.28" strokeWidth="0.6" strokeLinejoin="round" />
          ))}
        </g>
      ))}
      {TREES.map((t, i) => {
        const [bx, by] = proj([t.x, SLAB.y[1], t.z]);
        const [cx, cy] = proj([t.x, SLAB.y[1] + TREE_TRUNK + t.r * 0.55, t.z]);
        return (
          <g key={`t${i}`}>
            <line x1={bx} y1={by} x2={cx} y2={cy} stroke={COLORS.steel} strokeWidth="1.4" />
            <circle cx={cx} cy={cy} r={t.r * S} fill={COLORS.paper} stroke="#11110f" strokeOpacity="0.3" strokeWidth="0.6" />
          </g>
        );
      })}
      {FIGURES.map((f, i) => {
        const [x0, y0] = proj([f.x, f.y, f.z]);
        const [, y1] = proj([f.x, f.y + 0.36, f.z]);
        return <line key={`f${i}`} x1={x0} y1={y0} x2={x0} y2={y1} stroke={accent} strokeWidth="5" strokeLinecap="round" />;
      })}
    </svg>
  );
}

/**
 * The pavilion maquette as plain data (metres at model scale, y up, plinth top at y = 0), shared by the WebGL scene,
 * the baked ground-shadow texture and the SVG fallback drawing — one source, three renderings.
 */
export type Box = { x: [number, number]; y: [number, number]; z: [number, number] };

export const SLAB: Box = { x: [-2.35, 2.35], y: [0, 0.05], z: [-1.65, 1.65] };
export const PODIUM: Box = { x: [-2.05, 2.1], y: [0.05, 0.17], z: [-1.4, 0.98] };
export const CORE: Box = { x: [-1.9, -0.55], y: [0.17, 1.24], z: [-1.25, 0.05] };
export const ROOF: Box = { x: [-1.7, 2.05], y: [1.24, 1.3], z: [-1.12, 1.28] };
export const FIN: Box = { x: [1.8, 1.85], y: [0.17, 1.24], z: [-1.1, -0.05] };
export const GLASS: Box = { x: [-0.55, 1.8], y: [0.17, 1.24], z: [-0.86, -0.84] };
export const PLINTH: Box = { x: [-2.6, 2.6], y: [-0.46, 0], z: [-1.9, 1.9] };
/** Two treads (three risers) down from the podium edge to the slab. */
export const STEPS: Box[] = [1, 2].map((i) => ({ x: [-0.2, 0.9], y: [0.05, 0.17 - i * 0.04], z: [0.98 + (i - 1) * 0.12, 1.1 + (i - 1) * 0.12] }));
/** Slender steel columns carrying the cantilevered roof (x, z). */
export const COLUMNS: [number, number][] = [[0.25, 0.92], [1.55, 0.92], [1.55, -0.62], [0.25, -0.62]];
export const COLUMN_RADIUS = 0.028;
/** Foam trees: trunk base (x, z), crown radius. */
export const TREES: { x: number; z: number; r: number }[] = [{ x: -2.0, z: 1.25, r: 0.3 }, { x: 2.05, z: -1.32, r: 0.26 }, { x: -1.55, z: 1.38, r: 0.2 }];
export const TREE_TRUNK = 0.42;
/** Scale figures (x, z, standing surface y). */
export const FIGURES: { x: number; z: number; y: number }[] = [{ x: 0.95, z: 0.55, y: 0.17 }, { x: -0.65, z: 1.32, y: 0.05 }];
export const FIGURE_HEIGHT = 0.36;

/** Direction the key light comes FROM (normalised in use). Shadows are baked for it, so it stays fixed to the model. */
export const KEY_DIR: [number, number, number] = [-4, 6, 3];

export const COLORS = {
  board: '#8c8478',
  paper: '#f3efe6',
  basswood: '#d9c4a0',
  steel: '#2a2925',
};

'use client';
import { useThree } from '@react-three/fiber';
import { forwardRef, useEffect, useLayoutEffect, useMemo, useRef } from 'react';
import {
  BoxGeometry, CapsuleGeometry, CylinderGeometry, InstancedMesh, MeshBasicMaterial, MeshPhysicalMaterial, MeshStandardMaterial,
  NeutralToneMapping, Object3D, PlaneGeometry, SphereGeometry, Vector3, type PerspectiveCamera,
} from 'three';
import { LightingRig, OrbitInspect, type LightingPreset, type OrbitInspectHandle } from '../../three';
import { bakeShadowTexture, blobTexture, groundUv } from './bake';
import {
  CORE, COLORS, COLUMN_RADIUS, COLUMNS, FIGURE_HEIGHT, FIGURES, FIN, GLASS, KEY_DIR, PLINTH, PODIUM, ROOF, SLAB, STEPS, TREE_TRUNK, TREES, type Box,
} from './model';

export type LimitPreset = 'Upper hemisphere' | 'Front arc' | 'Plan to eye level';
export const LIMITS: Record<LimitPreset, { minPolar: number; maxPolar: number; minAz: number; maxAz: number }> = {
  'Upper hemisphere': { minPolar: 0.22, maxPolar: 1.36, minAz: -Infinity, maxAz: Infinity },
  'Front arc': { minPolar: 0.55, maxPolar: 1.34, minAz: -1.2, maxAz: 1.2 },
  'Plan to eye level': { minPolar: 0.02, maxPolar: 1.42, minAz: -Infinity, maxAz: Infinity },
};

/** Model-relative "home": three-quarter view from the front right. Narrow canvases step back to keep the plinth in frame. */
export const TARGET: [number, number, number] = [0.1, 0.42, 0];
const HOME = { azimuth: 0.62, polar: 1.02, distance: 11.2 };
export const MIN_DISTANCE = 5.2;
export const MAX_DISTANCE = 19;

const LIGHT: LightingPreset = {
  label: 'Maquette daylight',
  description: 'Low warm key from front left, cool sky fill, soft overhead panels.',
  exposure: 1,
  ambient: { color: '#fff6ea', intensity: 0.3 },
  key: { color: '#fff0dc', intensity: 2.3, position: KEY_DIR },
  fill: { color: '#dbe3f6', intensity: 0.55, position: [5, 3, -3] },
  env: {
    room: '#38342e',
    intensity: 0.55,
    panels: [
      { color: '#ffffff', intensity: 6, position: [0, 6, 0], size: [8, 8] },
      { color: '#ffe8cc', intensity: 3.5, position: [-6, 2.5, 3], size: [4, 5] },
      { color: '#dde6ff', intensity: 2, position: [6, 2, -3], size: [4, 5] },
    ],
  },
};

export interface ViewInfo { azimuth: number; elevation: number; zoom: number }

function ToneMapping() {
  const gl = useThree((s) => s.gl);
  const invalidate = useThree((s) => s.invalidate);
  useEffect(() => {
    const prev = gl.toneMapping;
    gl.toneMapping = NeutralToneMapping; // keeps paper white and the accent's hue (ACES would yellow them)
    invalidate();
    return () => { gl.toneMapping = prev; };
  }, [gl, invalidate]);
  return null;
}

type V3 = [number, number, number];
const size = (b: Box): V3 => [b.x[1] - b.x[0], b.y[1] - b.y[0], b.z[1] - b.z[0]];
const center = (b: Box): V3 => [(b.x[0] + b.x[1]) / 2, (b.y[0] + b.y[1]) / 2, (b.z[0] + b.z[1]) / 2];

function Maquette({ accent }: { accent: string }) {
  const invalidate = useThree((s) => s.invalidate);
  const res = useMemo(() => {
    const shadow = bakeShadowTexture();
    const blob = blobTexture();
    const mats = {
      board: new MeshStandardMaterial({ color: COLORS.board, roughness: 0.92 }),
      paper: new MeshStandardMaterial({ color: COLORS.paper, roughness: 0.9 }),
      wood: new MeshStandardMaterial({ color: COLORS.basswood, roughness: 0.78 }),
      steel: new MeshStandardMaterial({ color: COLORS.steel, roughness: 0.42, metalness: 0.6 }),
      glass: new MeshPhysicalMaterial({ color: '#d9e6e8', roughness: 0.06, metalness: 0, transparent: true, opacity: 0.26, envMapIntensity: 1.4, depthWrite: false }),
      figure: new MeshStandardMaterial({ color: accent, roughness: 0.55 }),
      shadow: new MeshBasicMaterial({ map: shadow, transparent: true, depthWrite: false, toneMapped: false, polygonOffset: true, polygonOffsetFactor: -2 }),
      blob: new MeshBasicMaterial({ map: blob, transparent: true, depthWrite: false, toneMapped: false, opacity: 0.55 }),
    };
    const box = new BoxGeometry(1, 1, 1);
    const ground = (b: Box) => {
      const g = new PlaneGeometry(b.x[1] - b.x[0], b.z[1] - b.z[0]);
      const { u, v } = groundUv(b);
      const uv = g.attributes.uv;
      for (let i = 0; i < uv.count; i++) uv.setXY(i, uv.getX(i) ? u[1] : u[0], uv.getY(i) ? v[1] : v[0]);
      return g;
    };
    const geos = {
      box,
      slabShadow: ground(SLAB),
      podiumShadow: ground(PODIUM),
      column: new CylinderGeometry(COLUMN_RADIUS, COLUMN_RADIUS, 1, 12),
      trunk: new CylinderGeometry(0.018, 0.024, 1, 8),
      crown: new SphereGeometry(1, 20, 14),
      figure: new CapsuleGeometry(0.045, FIGURE_HEIGHT - 0.09, 4, 10),
      blob: new PlaneGeometry(1, 1),
    };
    return { textures: [shadow, blob], mats, geos };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps -- accent is applied below without rebuilding

  useEffect(() => { res.mats.figure.color.set(accent); invalidate(); }, [accent, res, invalidate]);
  useEffect(() => () => {
    for (const t of res.textures) t?.dispose();
    for (const m of Object.values(res.mats)) m.dispose();
    for (const g of Object.values(res.geos)) g.dispose();
  }, [res]);

  const columns = useRef<InstancedMesh>(null);
  const trunks = useRef<InstancedMesh>(null);
  const crowns = useRef<InstancedMesh>(null);
  const figures = useRef<InstancedMesh>(null);
  const steps = useRef<InstancedMesh>(null);
  useLayoutEffect(() => {
    const o = new Object3D();
    const set = (mesh: InstancedMesh | null, i: number, p: V3, s: V3) => {
      if (!mesh) return;
      o.position.set(p[0], p[1], p[2]); o.scale.set(s[0], s[1], s[2]); o.rotation.set(0, 0, 0); o.updateMatrix();
      mesh.setMatrixAt(i, o.matrix);
      mesh.instanceMatrix.needsUpdate = true;
    };
    const colH = ROOF.y[0] - PODIUM.y[1];
    COLUMNS.forEach(([x, z], i) => set(columns.current, i, [x, PODIUM.y[1] + colH / 2, z], [1, colH, 1]));
    TREES.forEach((t, i) => {
      set(trunks.current, i, [t.x, SLAB.y[1] + TREE_TRUNK / 2, t.z], [1, TREE_TRUNK, 1]);
      set(crowns.current, i, [t.x, SLAB.y[1] + TREE_TRUNK + t.r * 0.55, t.z], [t.r, t.r * 0.92, t.r]);
    });
    FIGURES.forEach((f, i) => set(figures.current, i, [f.x, f.y + FIGURE_HEIGHT / 2, f.z], [1, 1, 1]));
    STEPS.forEach((b, i) => set(steps.current, i, center(b), size(b)));
    for (const m of [columns, trunks, crowns, figures, steps]) m.current?.computeBoundingSphere();
    invalidate();
  }, [invalidate]);

  const { mats, geos } = res;
  const solid = (b: Box, material: MeshStandardMaterial | MeshPhysicalMaterial, key: string) => (
    <mesh key={key} geometry={geos.box} material={material} position={center(b)} scale={size(b)} />
  );
  return (
    <group>
      <mesh geometry={geos.blob} material={mats.blob} rotation-x={-Math.PI / 2} position={[0.25, PLINTH.y[0] - 0.002, -0.1]} scale={[7.4, 5.6, 1]} renderOrder={-1} />
      {solid(PLINTH, mats.board, 'plinth')}
      {solid(SLAB, mats.paper, 'slab')}
      {solid(PODIUM, mats.paper, 'podium')}
      <instancedMesh ref={steps} args={[geos.box, mats.paper, STEPS.length]} />
      {solid(CORE, mats.wood, 'core')}
      {solid(FIN, mats.wood, 'fin')}
      {solid(ROOF, mats.paper, 'roof')}
      <instancedMesh ref={columns} args={[geos.column, mats.steel, COLUMNS.length]} />
      <instancedMesh ref={trunks} args={[geos.trunk, mats.steel, TREES.length]} />
      <instancedMesh ref={crowns} args={[geos.crown, mats.paper, TREES.length]} />
      <instancedMesh ref={figures} args={[geos.figure, mats.figure, FIGURES.length]} />
      {/* baked shadows, laid just above the slab and the podium */}
      <mesh geometry={geos.slabShadow} material={mats.shadow} rotation-x={-Math.PI / 2} position={[(SLAB.x[0] + SLAB.x[1]) / 2, SLAB.y[1] + 0.001, (SLAB.z[0] + SLAB.z[1]) / 2]} renderOrder={1} />
      <mesh geometry={geos.podiumShadow} material={mats.shadow} rotation-x={-Math.PI / 2} position={[(PODIUM.x[0] + PODIUM.x[1]) / 2, PODIUM.y[1] + 0.001, (PODIUM.z[0] + PODIUM.z[1]) / 2]} renderOrder={1} />
      {solid(GLASS, mats.glass, 'glass')}
    </group>
  );
}

export interface SceneProps {
  accent: string;
  damping: number;
  step: number;
  limits: LimitPreset;
  autoRotate: boolean;
  onView: (v: ViewInfo) => void;
  onSettle: () => void;
}

/** Spherical → position around TARGET. */
function homePosition(aspect: number): Vector3 {
  const d = HOME.distance * Math.min(1.9, Math.max(1, 1.35 / aspect));
  return new Vector3(Math.sin(HOME.polar) * Math.sin(HOME.azimuth), Math.cos(HOME.polar), Math.sin(HOME.polar) * Math.cos(HOME.azimuth))
    .multiplyScalar(d).add(new Vector3(...TARGET));
}

export const Scene = forwardRef<OrbitInspectHandle, SceneProps>(function Scene({ accent, damping, step, limits, autoRotate, onView, onSettle }, ref) {
  const camera = useThree((s) => s.camera) as PerspectiveCamera;
  const aspect = useThree((s) => s.size.width / Math.max(1, s.size.height));
  const invalidate = useThree((s) => s.invalidate);
  const orbit = useRef<OrbitInspectHandle | null>(null);
  const pristine = useRef(true);
  const home = useRef(new Vector3());
  const cb = useRef({ onView, onSettle });
  cb.current = { onView, onSettle };
  const lim = LIMITS[limits] ?? LIMITS['Upper hemisphere'];

  // Place the camera before OrbitInspect saves its "reset" pose; later aspect changes move the saved home too.
  useLayoutEffect(() => {
    home.current.copy(homePosition(aspect));
    const c = orbit.current?.controls;
    if (pristine.current || !c) { camera.position.copy(home.current); camera.lookAt(...TARGET); }
    if (c) { c.position0.copy(home.current); c.target0.set(...TARGET); if (pristine.current) c.update(); }
    invalidate();
  }, [aspect, camera, invalidate]);

  const report = () => {
    const c = orbit.current?.controls;
    if (!c) return;
    const az = ((c.getAzimuthalAngle() * 180) / Math.PI + 360) % 360;
    cb.current.onView({ azimuth: az, elevation: 90 - (c.getPolarAngle() * 180) / Math.PI, zoom: home.current.distanceTo(c.target) / Math.max(0.001, c.getDistance()) });
  };
  useEffect(() => { report(); }); // eslint-disable-line react-hooks/exhaustive-deps -- first paint + after prop changes

  const setRefs = (h: OrbitInspectHandle | null) => {
    orbit.current = h;
    if (typeof ref === 'function') ref(h); else if (ref) ref.current = h;
  };

  return (
    <>
      <ToneMapping />
      <LightingRig preset={LIGHT} shadow="none" />
      <Maquette accent={accent} />
      <OrbitInspect
        ref={setRefs}
        target={TARGET}
        damping={damping}
        keyboard={false}
        wheel="never"
        touchScroll="pan-y"
        keyStep={(step * Math.PI) / 180}
        minDistance={MIN_DISTANCE}
        maxDistance={MAX_DISTANCE}
        minPolarAngle={lim.minPolar}
        maxPolarAngle={lim.maxPolar}
        minAzimuthAngle={lim.minAz}
        maxAzimuthAngle={lim.maxAz}
        autoRotate={autoRotate}
        autoRotateSpeed={0.8}
        onStart={() => { pristine.current = false; }}
        onChange={report}
        onEnd={() => cb.current.onSettle()}
      />
    </>
  );
});

.root {
  container-type: inline-size;
  width: 100%;
  align-self: stretch;
  display: grid;
  grid-template-rows: 1fr auto;
  font-family: var(--s3-font-text, ui-sans-serif, system-ui, sans-serif);
  color: var(--s3-ink, #11110f);
}

.viewer {
  position: relative;
  min-height: clamp(300px, 58cqi, 500px);
  background: radial-gradient(110% 85% at 50% 42%, transparent 46%, var(--s3-surface-2, #e9e5da) 100%);
  outline: none;
}
.viewer:focus-visible { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: -2px; }
.viewer > [data-studio3-canvas] { position: absolute !important; inset: 0; }
.viewer canvas { cursor: grab; }
.viewer canvas:active { cursor: grabbing; }

.tag,
.readout {
  position: absolute;
  top: 12px;
  margin: 0;
  padding: 5px 10px;
  border: 1px solid var(--s3-line, #11110f24);
  border-radius: 999px;
  background: var(--s3-surface, #fbf9f4);
  font-family: var(--s3-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  white-space: nowrap;
  pointer-events: none;
}
.tag { left: 12px; color: var(--s3-ink-muted, #5c5a52); }
.readout { right: 12px; font-variant-numeric: tabular-nums; color: var(--s3-ink, #11110f); }
.readout:empty { display: none; }

.bar {
  display: grid;
  gap: 10px;
  padding: 12px clamp(12px, 3cqi, 24px) 14px;
  border-top: 1px solid var(--s3-line, #11110f24);
}
.toolbar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 18px; }
.group { display: inline-flex; align-items: center; gap: 4px; }
.legend {
  margin-right: 6px;
  font-family: var(--s3-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--s3-ink-muted, #5c5a52);
}
.toolbar button {
  display: inline-grid;
  grid-auto-flow: column;
  place-items: center;
  gap: 8px;
  min-width: 44px;
  height: 44px;
  padding: 0 10px;
  border: 1px solid var(--s3-line-strong, #11110f);
  border-radius: 999px;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: background-color var(--s3-duration-fast, 160ms) var(--s3-ease-standard, ease), color var(--s3-duration-fast, 160ms) var(--s3-ease-standard, ease);
}
.toolbar button svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.toolbar button:hover:not(:disabled) { background: var(--s3-ink, #11110f); color: var(--s3-surface, #fbf9f4); }
.toolbar button:focus-visible { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: 2px; }
.toolbar button:disabled { cursor: not-allowed; border-style: dashed; }
.reset { margin-left: auto; padding: 0 16px 0 12px !important; }

.hint { margin: 0; max-width: 72ch; font-size: 0.8125rem; line-height: 1.45; color: var(--s3-ink-muted, #5c5a52); }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }

@container (max-width: 520px) {
  .reset { margin-left: 0; }
  .readout { top: auto; bottom: 12px; }
}
@media (prefers-reduced-motion: reduce) {
  .toolbar button { transition: none; }
}
